import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"36、【明夷】 離下坤上","description":"橫渠易說 - 36、【明夷】 離下坤上","frontmatter":{"title":"36、【明夷】 離下坤上","description":"橫渠易說 - 36、【明夷】 離下坤上"},"headers":[],"relativePath":"classics/hengqu/038.md","filePath":"classics/hengqu/038.md"}'),l={name:"classics/hengqu/038.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_36、【明夷】-離下坤上" tabindex="-1">36、【明夷】 離下坤上 <a class="header-anchor" href="#_36、【明夷】-離下坤上" aria-label="Permalink to “36、【明夷】 離下坤上”">​</a></h1><h3 id="彖曰-明入地中-明夷-內文明而外柔順-以蒙大難-文王以之。-利艱貞-晦其明也-內難而能正其志-箕子以之。" tabindex="-1">彖曰：明入地中，明夷，內文明而外柔順，以蒙大難，文王以之。“利艱貞”，晦其明也，內難而能正其志，箕子以之。 <a class="header-anchor" href="#彖曰-明入地中-明夷-內文明而外柔順-以蒙大難-文王以之。-利艱貞-晦其明也-內難而能正其志-箕子以之。" aria-label="Permalink to “彖曰：明入地中，明夷，內文明而外柔順，以蒙大難，文王以之。“利艱貞”，晦其明也，內難而能正其志，箕子以之。”">​</a></h3><p>文王體一卦之用，箕子以六五一爻之德，文王難在外，箕子難在內也。</p><h3 id="象曰-明入地中-明夷-君子以蒞眾用晦而明。" tabindex="-1">象曰：明入地中，明夷，君子以蒞眾用晦而明。 <a class="header-anchor" href="#象曰-明入地中-明夷-君子以蒞眾用晦而明。" aria-label="Permalink to “象曰：明入地中，明夷，君子以蒞眾用晦而明。”">​</a></h3><p>不任察而不失其治也。</p><h3 id="初九-明夷于飛-垂其翼。君子於行-三日不食。有攸往-主人有言。-象曰-君子於行-義不食也。" tabindex="-1">初九，明夷于飛，垂其翼。君子於行，三日不食。有攸往，主人有言。 象曰：“君子於行”，義不食也。 <a class="header-anchor" href="#初九-明夷于飛-垂其翼。君子於行-三日不食。有攸往-主人有言。-象曰-君子於行-義不食也。" aria-label="Permalink to “初九，明夷于飛，垂其翼。君子於行，三日不食。有攸往，主人有言。 象曰：“君子於行”，義不食也。”">​</a></h3><p>進應於上，為三所困，故曰“于飛垂翼”。君子避患當速，勢不與抗，退而遠行，不遑暇食，靜以自守，非有所往之時也。</p><h3 id="六二-明夷-夷於左股。用拯馬壯-吉。-象曰-六二之吉-順以則也。" tabindex="-1">六二，明夷，夷於左股。用拯馬壯，吉。 象曰：六二之吉，順以則也。 <a class="header-anchor" href="#六二-明夷-夷於左股。用拯馬壯-吉。-象曰-六二之吉-順以則也。" aria-label="Permalink to “六二，明夷，夷於左股。用拯馬壯，吉。 象曰：六二之吉，順以則也。”">​</a></h3><p>與三同體，三為六應，故曰“夷於左股”，居中履順，難不能及，故曰“用拯馬壯吉”。馬謂初九，亦為己用，故欲拯闇同。</p><h3 id="九三-明夷於南狩-得其大首-不可疾-貞。-象曰-南狩之志-乃大得也。" tabindex="-1">九三，明夷於南狩，得其大首，不可疾，貞。 象曰：南狩之志，乃大得也。 <a class="header-anchor" href="#九三-明夷於南狩-得其大首-不可疾-貞。-象曰-南狩之志-乃大得也。" aria-label="Permalink to “九三，明夷於南狩，得其大首，不可疾，貞。 象曰：南狩之志，乃大得也。”">​</a></h3><p>九三進獲明夷之主，故曰“南狩得其大首”。</p><h3 id="六四-入於左腹-獲明夷之心-於出門庭。-象曰-入於左腹-獲心意也。" tabindex="-1">六四，入於左腹，獲明夷之心，於出門庭。 象曰：“入於左腹”，獲心意也。 <a class="header-anchor" href="#六四-入於左腹-獲明夷之心-於出門庭。-象曰-入於左腹-獲心意也。" aria-label="Permalink to “六四，入於左腹，獲明夷之心，於出門庭。 象曰：“入於左腹”，獲心意也。”">​</a></h3><p>與上六同為一體，故曰“入於左腹”，與五親比，故曰“出門”“獲明夷之心”。蓋用柔履中，其志相得，故曰“獲心意”也。</p><h3 id="六五-箕子之明夷-利貞。-象曰-箕子之貞-明不可息也。" tabindex="-1">六五，箕子之明夷，利貞。 象曰：箕子之貞，明不可息也。 <a class="header-anchor" href="#六五-箕子之明夷-利貞。-象曰-箕子之貞-明不可息也。" aria-label="Permalink to “六五，箕子之明夷，利貞。 象曰：箕子之貞，明不可息也。”">​</a></h3><p>雖近於闇，然柔順履中，闇不能掩，箕子之正也。</p><h3 id="上六-不明晦-初登於天-後入於地。-象曰-初登於天-照四國也-後入於地-失則也。" tabindex="-1">上六，不明晦，初登於天，後入於地。 象曰：“初登於天”，照四國也；“後入於地”，失則也。 <a class="header-anchor" href="#上六-不明晦-初登於天-後入於地。-象曰-初登於天-照四國也-後入於地-失則也。" aria-label="Permalink to “上六，不明晦，初登於天，後入於地。 象曰：“初登於天”，照四國也；“後入於地”，失則也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
